UPDATE audit_logs SET entity_type = CASE
  WHEN split_part(action,'.',1) IN ('users','auth') THEN 'user'
  WHEN split_part(action,'.',1) = 'customers' THEN 'customer'
  WHEN split_part(action,'.',1) = 'vehicles' THEN 'vehicle'
END;--> statement-breakpoint
