-- ALTER TABLE locks remain held until commit: inserts cannot race the maximum ID.
DO $$
DECLARE table_name text; max_id bigint;
BEGIN
  FOREACH table_name IN ARRAY ARRAY['users','sessions','audit_logs','idempotency_records','outbox_jobs',
    'pricing_groups','vehicle_brands','vehicle_models','equivalence_groups','customers','customer_notes','vehicles','vehicle_service_records']
  LOOP
    EXECUTE format('SELECT max(id) FROM %I', table_name) INTO max_id;
    PERFORM setval(pg_get_serial_sequence(table_name, 'id'), coalesce(max_id, 1), max_id IS NOT NULL);
  END LOOP;
END $$;--> statement-breakpoint
